head.script:
    requires("uiplugin.popup");
	scwin.onpageload = function() {
		dataList1.setData(["a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f","a","b","c","d","e","f"])
        //$p.executeSubmission("submission1");
        //gridView1.hide();
	};

	scwin.onpageunload = function() {

	};

    scwin.submission1_submitdone = function() {
    debugger;

        //gridView1.show();
    };

	scwin.trigger1_onclick = function(e) {
            option = { 
                  id : "submission2"
                , action : "sleep.jsp"
                , target : "data:json,{'id':'dataList1','key':'dataList1'},{'id':'dataList2','key':'dataList2'}"
                , submitDoneHandler : "scwin.submission1_submitdone"
                , processMsg : "...1" 
                , encoding : "UTF-8"
                , method : "post"
                , mediatype : "application/json" 
                , mode : "async"
            };
        $p.createSubmission( option );
		$p.executeSubmission("submission2");
	};

    scwin.trigger2_onclick = function(e) {
        var url = "submission_process_modal_WESD-1286_(WSQ-5254)_popup.xml"
        var options = {
            "id": "AuthorityMemberPop",
            "type": "wframePopup",
            "width": "560px",
            "height": "400px",
            "top": "246px",
            "left": "241.5px",
            "popupName": "직원 조회",
            "modal": true,
            "useModalStack": true,
            "style": "",
            "srcData": null,
            "destData": null,
            "xml": null,
            "resizable": true,
            "status": false,
            "menubar": false,
            "scrollbars": true,
            "title": false,
            "useMaximize": false,
            "useModalDisable": false,
            "closeAction": "",
            "className": "",
            "fullscreen": false,
            "useControl": false,
            "foldOnMinimized": false,
            "controls": {
                "minimize": false,
                "maximize": false,
                "close": false
            },
            "foldSize": {
            "width": 500
            },
            "useATagBtn": false,
            "disableCloseButton": false,
            "alwaysOnTop": false,
            "popupUrl": "../popup.html",
            "processMsgFrame": false,
            "frameModal": scwin.$w.getFrameId(),
            "isPopupCloseAction": true,
            "popupCloseAction": "scwin.closeActionFnc",
            "windowDragMove": true
        }
        $p.openPopup( url, options);
    }; 

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('___processbar2').style.zIndex > 1;
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('AuthorityMemberPop_wframe_trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
